import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider. The {@code readFrom} method now
 * creates a fresh {@link Parser} for each invocation and configures the
 * {@link ParserOptions} *before* parsing to guarantee that entity resolution
 * (including external entities) is disabled. This eliminates the XXE risk that
 * existed when the options were set inside a synchronized block on a shared
 * parser instance.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // -----------------------------------------------------------------------
    //  Secure readFrom implementation
    // -----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type genericType,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        if (entityStream == null) {
            throw new IllegalArgumentException("Input stream is null");
        }

        // Obtain a *new* parser instance for this call – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options with the safest defaults.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable resolution of external entities (XXE protection).
        options.setResolveEntities(false);

        // Some Abdera versions expose an additional flag to prevent expansion of
        // entity references. If present, set it to false via reflection to keep
        // the code compatible with multiple library versions.
        try {
            java.lang.reflect.Method expandMethod =
                    ParserOptions.class.getMethod("setExpandEntityReferences", boolean.class);
            expandMethod.invoke(options, Boolean.FALSE);
        } catch (NoSuchMethodException ignored) {
            // Method not available – the earlier call to setResolveEntities is
            // sufficient for the versions that lack this method.
        } catch (Exception e) {
            // Any reflection failure should not prevent parsing; log if a
            // logging framework is available, otherwise ignore.
        }

        // Parse the stream using the securely configured options.
        Document<T> doc = parser.parse(entityStream, options);
        return doc.getRoot();
    }

    // -----------------------------------------------------------------------
    //  Other abstract/provider methods would follow...
    // -----------------------------------------------------------------------
}
