    /** Fallback regular expression – simple, safe and bounded in size. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp)://[\\w.-]+(?::\\d{1,5})?(?:/[^\\s]*)?$";

    private String urlRegex;
    private String urlRegexExpression;

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Returns a regular expression used for client‑side URL validation.
     * <p>
     * The method now defensively handles {@code null} and empty values for
     * {@code urlRegexExpression} and {@code urlRegex}.  If a non‑empty
     * {@code urlRegexExpression} is supplied it is parsed; any parsing error
     * results in a graceful fallback to the default regex.  This prevents
     * unexpected {@code NullPointerException}s or uncontrolled large regexes
     * that could be exploited for a denial‑of‑service attack.
     *
     * @return a safe regular expression string
     */
    public String getUrlRegex() {
        // 1. Prefer a user‑supplied expression if it is non‑null / non‑empty.
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String) {
                    String result = ((String) parsed).trim();
                    if (!result.isEmpty()) {
                        return result;
                    }
                }
            } catch (Exception e) {
                // Parsing failed – log and fall back to the safe default.
                LOG.warn("Failed to parse urlRegexExpression '{}': {}", urlRegexExpression, e.toString());
            }
