        // 2. Fallback to the explicitly configured regex if present.
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex.trim();
        }

        // 3. Final fallback – a concise, well‑bounded regex that validates
        //    http, https and ftp URLs without the risk of catastrophic back‑tracking.
        return DEFAULT_URL_REGEX;
    }

    // -----------------------------------------------------------------------
    // Additional helper / parsing logic (inherited from FieldValidatorSupport)
    // -----------------------------------------------------------------------
}
