static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Remove query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Normalize and validate path
    File file = new File(dir, name);
    try {
        Path canonicalDir = dir.getCanonicalFile().toPath();
        Path canonicalFile = file.getCanonicalFile().toPath();

        if (!canonicalFile.startsWith(canonicalDir)) {
            throw new IllegalArgumentException("Invalid file name: path traversal detected");
        }
    } catch (IOException e) {
        throw new IllegalStateException("Failed to resolve file paths", e);
    }

    // Determine unique file name if exists
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
        // Ensure still inside dir (should be)
        try {
            if (!file.getCanonicalFile().toPath().startsWith(dir.getCanonicalFile().toPath())) {
                throw new IllegalArgumentException("Generated file name escapes target directory");
            }
        } catch (IOException e) {
            throw new IllegalStateException("Failed to resolve generated file path", e);
        }
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}

