private void doInclude(HttpServletRequest request, HttpServletResponse response, String resourceUrl)
        throws ServletException, IOException {
    if (this.contentType != null) {
        response.setContentType(this.contentType);
    }

    if (!StringUtils.hasText(resourceUrl)) {
        // nothing to include
        return;
    }

    // Split the incoming string using the defined delimiters.
    String[] resourceUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);
    for (String url : resourceUrls) {
        // ---- BEGIN INPUT SANITISATION ----
        // Reject encoded traversal sequences.
        String decoded = java.net.URLDecoder.decode(url, request.getCharacterEncoding() != null
                ? request.getCharacterEncoding() : "UTF-8");
        // Normalise the path – this removes “..”, “.” and duplicate separators.
        java.nio.file.Path normalizedPath;
        try {
            normalizedPath = java.nio.file.Paths.get(decoded).normalize();
        } catch (InvalidPathException e) {
            throw new ServletException("Invalid resource path: [" + url + "]", e);
        }

        // Disallow absolute paths.
        if (normalizedPath.isAbsolute()) {
            throw new ServletException("Absolute paths are not allowed: [" + url + "]");
        }

        // Disallow any traversal that would escape the current context.
        // After normalization a leading ".." indicates an attempt to go up.
        if (normalizedPath.startsWith("..")) {
            throw new ServletException("Path traversal detected in resource: [" + url + "]");
        }

        // Disallow Windows back‑slash separators which could be used to bypass checks.
        if (decoded.contains("\\") || url.contains("\\")) {
            throw new ServletException("Back‑slash characters are not allowed in resource paths: [" + url + "]");
        }

        // Additional defensive check for encoded ".." sequences that may have survived decoding.
        if (decoded.contains("..")) {
            throw new ServletException("Path traversal sequence '..' detected in resource: [" + url + "]");
        }
        // ---- END INPUT SANITISATION ----

        // Verify the (original) URL against the whitelist pattern, if one is configured.
        if (this.allowedResources != null && !this.pathMatcher.match(this.allowedResources, url)) {
            throw new ServletException(
                    "Resource [" + url + "] does not match allowed pattern [" + this.allowedResources + "]");
        }

        if (logger.isDebugEnabled()) {
            logger.debug("Including resource [" + url + "]");
        }

        RequestDispatcher rd = request.getRequestDispatcher(url);
        if (rd == null) {
            throw new ServletException("No RequestDispatcher found for resource [" + url + "]");
        }
        rd.include(request, response);
    }
