private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    // Resolve the canonical (real) path of the target directory once.
    Path targetDirRealPath = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);

    ArchiveEntry entry;
    while ((entry = supplier.getNextReadableEntry()) != null) {
        String entryName = entry.getName();

        // Reject null, empty, absolute or traversal components early.
        if (entryName == null || entryName.isEmpty()) {
            throw new IOException("Archive entry name is empty");
        }
        // Normalize separators to the system default for Path resolution.
        entryName = entryName.replace('/', File.separatorChar).replace('\\', File.separatorChar);

        // Disallow absolute paths.
        if (new File(entryName).isAbsolute()) {
            throw new IOException("Entry name '" + entryName + "' is absolute");
        }

        // Resolve the entry against the target directory and normalize the result.
        Path entryPath = targetDirRealPath.resolve(entryName).normalize();

        // Ensure the resulting path is still inside the target directory.
        if (!entryPath.startsWith(targetDirRealPath)) {
            throw new IOException("Entry '" + entry.getName() + "' would escape target directory");
        }

        if (entry.isDirectory()) {
            // Create the directory (including any missing parents). Do not follow symlinks.
            Files.createDirectories(entryPath);
        } else {
            // Ensure parent directory exists.
            Path parent = entryPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            // Write the entry data to the file. Use CREATE_NEW to avoid overwriting existing files
            // that could be symlinks pointing outside the target directory.
            try (OutputStream out = Files.newOutputStream(entryPath,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(entry, out);
            }
        }
    }
}
