private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();
    // Guard against unknown or negative size – treat as EOF if we cannot determine size.
    if (csize < 0) {
        // Fallback to caching the entry so we know its size.
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    // If we have already read the declared size, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Fill internal buffer if empty.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // Underlying stream ended before we reached the declared size.
            // Signal EOF to avoid an infinite loop.
            return -1;
        }
        if (l == 0) {
            // Defensive: treat zero‑length read as EOF.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine how many bytes we can safely return.
    int toRead = Math.min(buf.remaining(), length);
    long remainingEntryBytes = csize - current.bytesRead;
    if (remainingEntryBytes <= 0) {
        // No more bytes expected for this entry.
        return -1;
    }
    if (remainingEntryBytes < toRead) {
        toRead = (int) remainingEntryBytes;
    }

    // If after all calculations there is nothing to read, signal EOF.
    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
