     * @param toVersion   the end version (may be {@code null})
     * @return a negative integer, zero, or a positive integer as
     *         {@code fromVersion} is less than, equal to, or greater than
     *         {@code toVersion}
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        int[] from = parseVersion(fromVersion);
        int[] to   = parseVersion(toVersion);

        // compare major, then minor, then patch
        for (int i = 0; i < 3; i++) {
            int diff = from[i] - to[i];
            if (diff != 0) {
                return diff;
            }
        }
        return 0;
    }

    /**
     * Parses a version string into an {@code int[3]} containing
     * {@code [major, minor, patch]}. Missing components are filled with {@code 0}.
     * Non‑numeric components are ignored and also result in {@code 0}.
     *
     * @param version the version string, may be {@code null}
     * @return an array of three integers representing the version
     */
    private static int[] parseVersion(String version) {
        int[] result = new int[3]; // defaults to 0
        if (version == null) {
            return result;
        }

        // Trim whitespace and split – limit to 3 parts to avoid unnecessary array growth
        String[] parts = version.trim().split("\\.", 3);
        for (int i = 0; i < parts.length && i < 3; i++) {
            try {
                result[i] = Integer.parseInt(parts[i].trim());
            } catch (NumberFormatException ignored) {
                // Invalid numeric part – keep default 0
            }
        }
        return result;
    }

