import javax.xml.XMLConstants;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import org.apache.camel.Converter;
import org.apache.camel.Exchange;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;
import org.xml.sax.helpers.XMLReaderFactory;

/**
 * Utility class that converts XML payloads to {@link SAXSource} instances.
 *
 * <p>The implementation is hardened against XML External Entity (XXE) attacks.
 * All external entity processing is explicitly disabled and DOCTYPE
 * declarations are disallowed. The code also guarantees that a non‑null
 * {@link XMLReader} is returned – otherwise a {@link SAXException} is thrown,
 * preventing downstream NPEs.</p>
 */
@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // -------------------------------------------------------------------------
    // Public conversion method (hard‑ended against XXE)
    // -------------------------------------------------------------------------

    /**
     * Creates a {@link SAXSource} from a {@link StreamSource} while ensuring that
     * the underlying {@link XMLReader} is configured to reject external entities
     * and DTDs.
     *
     * @param source   the incoming XML source; must provide either a {@link java.io.Reader}
     *                 or an {@link java.io.InputStream}
     * @param exchange the Camel exchange – may contain a pre‑configured
     *                 {@link SAXParserFactory} under the key {@link Exchange#SAXPARSER_FACTORY}
     * @return a {@link SAXSource} ready for safe processing
     * @throws SAXException if a secure {@link XMLReader} cannot be created
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        if (source == null) {
            throw new IllegalArgumentException("StreamSource must not be null");
        }

        // -----------------------------------------------------------------
        // Build the InputSource from the StreamSource (reader preferred)
        // -----------------------------------------------------------------
        InputSource inputSource;
        try {
            if (source.getReader() != null) {
                inputSource = new InputSource(source.getReader());
            } else if (source.getInputStream() != null) {
                inputSource = new InputSource(source.getInputStream());
            } else {
                throw new IllegalArgumentException("StreamSource must provide a Reader or InputStream");
            }
        } catch (Exception e) {
            // Defensive – should never happen, but we keep the contract clear.
            throw new SAXException("Failed to create InputSource from StreamSource", e);
        }

        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        // ---------------------------------------------------------------
        // Obtain (or create) a SAXParserFactory and harden it against XXE
        // ---------------------------------------------------------------
        SAXParserFactory factory = null;
        if (exchange != null) {
            factory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
        }
        if (factory == null) {
            factory = SAXParserFactory.newInstance();
        }

        // The factory must be namespace‑aware for the rest of the code.
        factory.setNamespaceAware(true);
        // Disable validation – we only need a safe parser.
        factory.setValidating(false);

        // -----------------------------------------------------------------
        // Apply the security‑hardening features. All feature‑setting is wrapped
        // individually so that a parser that does not support a particular
        // feature does not prevent the others from being applied.
        // -----------------------------------------------------------------
        setFeatureSafely(factory, XMLConstants.FEATURE_SECURE_PROCESSING, true);
        setFeatureSafely(factory, "http://xml.org/sax/features/external-general-entities", false);
        setFeatureSafely(factory, "http://xml.org/sax/features/external-parameter-entities", false);
        setFeatureSafely(factory, "http://apache.org/xml/features/disallow-doctype-decl", true);
        // The following two features are specific to Xerces‑based parsers;
        // they are optional but improve safety when supported.
        setFeatureSafely(factory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        setFeatureSafely(factory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

        // ---------------------------------------------------------------
        // Create the XMLReader. If the factory fails we fall back to the
        // generic XMLReaderFactory (still applying the same hardening).
        // ---------------------------------------------------------------
        XMLReader xmlReader;
        try {
            SAXParser parser = factory.newSAXParser();
            xmlReader = parser.getXMLReader();
        } catch (ParserConfigurationException | SAXException e) {
            LOG.warn("Secure SAXParserFactory failed, falling back to XMLReaderFactory: {}", e.getMessage());
            xmlReader = createFallbackReader();
        }

        if (xmlReader == null) {
            throw new SAXException("Unable to obtain a secure XMLReader");
        }

        // ---------------------------------------------------------------
        // Return the hardened SAXSource.
        // ---------------------------------------------------------------
        return new SAXSource(xmlReader, inputSource);
    }

    // -------------------------------------------------------------------------
    // Helper methods
    // -------------------------------------------------------------------------

    /**
     * Sets a feature on a {@link SAXParserFactory} while swallowing any
     * {@link ParserConfigurationException} or {@link SAXException} that may be
     * thrown if the underlying parser does not recognise the feature.
     *
     * @param factory the factory to configure
     * @param name    the fully‑qualified feature name
     * @param value   the value to set
     */
    private static void setFeatureSafely(SAXParserFactory factory, String name, boolean value) {
        try {
            factory.setFeature(name, value);
        } catch (ParserConfigurationException | SAXException e) {
            LOG.warn("SAXParserFactory does not support feature {} (value {}): {}", name, value, e.getMessage());
        } catch (Exception e) {
            LOG.warn("Unexpected error while setting feature {}: {}", name, e.getMessage());
        }
    }

    /**
     * Creates an {@link XMLReader} via {@link XMLReaderFactory} and applies the
     * same XXE‑hardening features as {@link #toSAXSourceFromStream}.
     *
     * @return a hardened XMLReader, or {@code null} if creation fails
     */
    private static XMLReader createFallbackReader() {
        try {
            XMLReader reader = XMLReaderFactory.createXMLReader();
            // Apply the same hardening as for the factory.
            setFeatureSafely(reader, "http://xml.org/sax/features/external-general-entities", false);
            setFeatureSafely(reader, "http://xml.org/sax/features/external-parameter-entities", false);
            setFeatureSafely(reader, "http://apache.org/xml/features/disallow-doctype-decl", true);
            setFeatureSafely(reader, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            setFeatureSafely(reader, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            return reader;
        } catch (SAXException e) {
            LOG.warn("Failed to create fallback XMLReader: {}", e.getMessage());
            return null;
        }
    }

    /**
     * Sets a feature on an {@link XMLReader} while handling possible exceptions.
     *
     * @param reader the XMLReader to configure
     * @param name   the feature name
     * @param value  the desired value
     */
    private static void setFeatureSafely(XMLReader reader, String name, boolean value) {
        try {
            reader.setFeature(name, value);
        } catch (SAXException e) {
            LOG.warn("XMLReader does not support feature {} (value {}): {}", name, value, e.getMessage());
        } catch (Exception e) {
            LOG.warn("Unexpected error while setting XMLReader feature {}: {}", name, e.getMessage());
        }
    }
