    /**
     * Creates a secure {@link XMLStreamReader} that is protected against XML External Entity (XXE) attacks.
     * <p>
     * The {@link XMLInputFactory} is configured to:
     * <ul>
     *   <li>Disable DTD processing ({@code XMLInputFactory.SUPPORT_DTD = false})</li>
     *   <li>Disable external entity resolution ({@code XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES = false})</li>
     *   <li>Enable coalescing and entity reference replacement (as originally intended)</li>
     * </ul>
     *
     * @param inputStream the raw XML input stream (must not be {@code null})
     * @return a configured {@link XMLStreamReader}
     * @throws XMLStreamException if the underlying parser cannot be created
     * @throws IOException        if an I/O error occurs while wrapping the stream
     */
    private static final XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        if (inputStream == null) {
            throw new NullPointerException("inputStream must not be null");
        }

        XMLInputFactory factory = XMLInputFactory.newInstance();

        // Preserve original behaviour
        factory.setProperty(XMLInputFactory.IS_COALESCING, true);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, true);

        // Harden against XXE
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);

        // Create the reader on a stream that strips any unwanted XML prefix
        return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
    }

