    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Returns {@code true} if the request is allowed to modify the user identified
     * by the path variable.  The method now:
     * <ul>
     *   <li>Ensures the request is authenticated.</li>
     *   <li>Verifies that the authenticated principal’s ID matches the user ID
     *       being updated (or that the caller has an admin role).</li>
     *   <li>Performs null‑safe comparisons of immutable fields that must not be
     *       changed by a self‑update.</li>
