        // 1.  Authentication / Authorization check
        // --------------------------------------------------------------------
        String authenticatedUserId = extractAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            // No authenticated principal – deny the request.
            return false;
        }

        // Extract the user ID from the request URL (e.g. /Users/{id})
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // If the caller is not updating their own record, they must be an admin.
        if (!authenticatedUserId.equals(targetUserId) && !request.isUserInRole("uaa.admin")) {
            return false;
        }

        // --------------------------------------------------------------------
        // 2.  Load the persisted user (if it does not exist we allow the
        //     operation to continue – the provisioning layer will handle the
        //     creation case).
        // --------------------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot compare immutable fields;
            // let the caller proceed (the provisioning layer will reject an
            // illegal creation later).
            return true;
        }

        // --------------------------------------------------------------------
        // 3.  Parse the request payload safely.
        // --------------------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            // Malformed payload – deny.
            return false;
